<?php /** @var array $by @var int $total @var int $red @var int $late */ ?>
<div class="page-head"><div><h1><?= icon('target') ?> <?= e(t('strat.title')) ?></h1><p class="sub"><?= e(t('strat.subtitle')) ?></p></div>
  <div class="actions noprint"><?php if (can('strategy.manage')): ?><a class="btn gold" href="<?= e(url('strategy/new')) ?>"><?= e(t('strat.new')) ?></a><?php endif; ?><button class="btn secondary" type="button" data-print><?= e(t('common.print')) ?></button></div></div>
<div class="kpis"><div class="kpi"><div class="v"><?= (int)$total ?></div><div class="l"><?= e(t('strat.stat_total')) ?></div></div><div class="kpi <?= $red ? 'alert' : '' ?>"><div class="v"><?= (int)$red ?></div><div class="l"><?= e(t('strat.stat_red')) ?></div></div><div class="kpi <?= $late ? 'alert' : '' ?>"><div class="v"><?= (int)$late ?></div><div class="l"><?= e(t('strat.stat_late')) ?></div></div></div>
<?php foreach ($by as $persp => $list): ?><section class="card"><h2><?= e(t('enum.persp.' . $persp)) ?> <span class="count badge"><?= count($list) ?></span></h2>
<?php if (!$list): ?><p class="muted"><?= e(t('strat.none_in_persp')) ?></p><?php endif; ?>
<?php foreach ($list as $o): ?><a class="obj" href="<?= e(url('strategy/' . $o['id'])) ?>"><div class="obj-head"><strong><?= e($o['code']) ?> — <?= e($o['title']) ?></strong><span class="badge <?= $o['rag'] === 'green' ? 'ok' : ($o['rag'] === 'amber' ? 'warn' : 'danger') ?>"><?= (int)$o['progress'] ?>%</span></div>
<div class="meter" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?= (int)$o['progress'] ?>"><span class="fill <?= e($o['rag']) ?>" style="width:<?= (int)$o['progress'] ?>%"></span></div>
<div class="obj-meta"><?= e($o['owner_name']) ?> · <?= e(\App\Core\Money::plain($o['current_value']) . ' / ' . \App\Core\Money::plain($o['target']) . ' ' . $o['unit']) ?> · <?= e(fdate($o['due_date'])) ?><?= $o['late'] ? ' <span class="badge danger">' . e(t('my.overdue')) . '</span>' : '' ?> · <?= (int)$o['risk_n'] ?> <?= e(t('strat.risks_short')) ?></div></a><?php endforeach; ?></section><?php endforeach; ?>
